import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Split-K tiled GEMM: C[M,N] += A[M,K] @ B[K,N]
// Each CTA computes a (128,128) tile of C, accumulating over a
// contiguous range of K-tiles determined by blockIdx.z, then
// atomically adds its partial result into global C.
// Uses double-buffered (software pipelined) shared memory staging so that
// the global->shared load of the next K-tile can overlap with the
// shared-memory GEMM compute of the current K-tile.
constexpr int SMEM_PAD = 4; // padding (elements) added to shared-memory tile
                             // leading dimension to avoid bank conflicts.
template <class TA, class TB, class TC>
__global__ static void
gemm_splitk_device(cute::Shape<int,int,int> shape_MNK,
                    int kTilesPerBlock, int totalKTiles,
                    TA const* A, cute::Stride<int,int> dA,
                    TB const* B, cute::Stride<int,int> dB,
                    TC      * C, cute::Stride<int,int> dC)
{
  using namespace cute;
  // Full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(get<0>(shape_MNK), get<2>(shape_MNK)), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(get<2>(shape_MNK), get<1>(shape_MNK)), dB); // (K,N)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(get<0>(shape_MNK), get<1>(shape_MNK)), dC); // (M,N)
  // Tile
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<32>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{});
  // Double-buffered shared memory (dynamic, opt-in via cudaFuncSetAttribute)
  // The A/B tile buffers are padded along their leading dimension (from 128
  // to 128+SMEM_PAD elements) so that the stride between consecutive
  // K-slices (for A) / N-slices (for B) is no longer a multiple of the
  // 32-way shared-memory bank width, eliminating the systematic bank
  // conflicts that the un-padded (stride == 128) layout would otherwise
  // incur during the per-thread reads performed inside gemm().
  extern __shared__ unsigned char smem_raw[];
  constexpr int SMEM_LD = 128 + SMEM_PAD;
  TA* smemA0 = reinterpret_cast<TA*>(smem_raw);
  TA* smemA1 = smemA0 + SMEM_LD*32;
  TB* smemB0 = reinterpret_cast<TB*>(smemA1 + SMEM_LD*32);
  TB* smemB1 = smemB0 + SMEM_LD*32;
  auto smem_layout = make_layout(make_shape(Int<128>{}, Int<32>{}), make_stride(Int<1>{}, Int<SMEM_LD>{}));
  Tensor sA0 = make_tensor(make_smem_ptr(smemA0), smem_layout);
  Tensor sA1 = make_tensor(make_smem_ptr(smemA1), smem_layout);
  Tensor sB0 = make_tensor(make_smem_ptr(smemB0), smem_layout);
  Tensor sB1 = make_tensor(make_smem_ptr(smemB1), smem_layout);
  // Thread layouts
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tAgA  = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA0 = local_partition(sA0, tA, threadIdx.x);
  Tensor tAsA1 = local_partition(sA1, tA, threadIdx.x);
  Tensor tBgB  = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB0 = local_partition(sB0, tB, threadIdx.x);
  Tensor tBsB1 = local_partition(sB1, tB, threadIdx.x);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC  = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  int k_tile_start = blockIdx.z * kTilesPerBlock;
  int k_tile_end   = min(k_tile_start + kTilesPerBlock, totalKTiles);
  if (k_tile_start < k_tile_end) {
    // Prologue: load the first K-tile into buffer 0.
    copy(tAgA(_,_,k_tile_start), tAsA0);
    copy(tBgB(_,_,k_tile_start), tBsB0);
    __syncthreads();
    int buf = 0;
    for (int k_tile = k_tile_start; k_tile < k_tile_end; ++k_tile) {
      int next_tile = k_tile + 1;
      // Prefetch the next K-tile into the other buffer while this
      // iteration's compute (below) uses the currently-ready buffer.
      // Since the prefetch and the compute touch independent data,
      // the SM can overlap the long-latency global loads with the
      // shared-memory GEMM math instead of serializing them.
      if (next_tile < k_tile_end) {
        if (buf == 0) {
          copy(tAgA(_,_,next_tile), tAsA1);
          copy(tBgB(_,_,next_tile), tBsB1);
        } else {
          copy(tAgA(_,_,next_tile), tAsA0);
          copy(tBgB(_,_,next_tile), tBsB0);
        }
      }
      if (buf == 0) {
        gemm(tCsA0, tCsB0, tCrC);
      } else {
        gemm(tCsA1, tCsB1, tCrC);
      }
      __syncthreads();
      buf ^= 1;
    }
  }
  // Atomic epilogue: accumulate partial results from split-K blocks
  CUTE_UNROLL
  for (int i = 0; i < size(tCrC); ++i) {
    atomicAdd(&tCgC(i), tCrC(i));
  }
}
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int K2 = (int)B.size(0);
  int N = (int)B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions must match");
  constexpr int BLK_M = 128, BLK_N = 128, BLK_K = 32;
  TORCH_CHECK(M % BLK_M == 0, "M must be divisible by 128");
  TORCH_CHECK(N % BLK_N == 0, "N must be divisible by 128");
  TORCH_CHECK(K % BLK_K == 0, "K must be divisible by 32");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::zeros({M, N}, A.options());
  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();
  auto dA = make_stride(K, 1); // row-major (M,K)
  auto dB = make_stride(N, 1); // row-major (K,N)
  auto dC = make_stride(N, 1); // row-major (M,N)
  auto shape_MNK = make_shape(M, N, K);
  int totalKTiles = K / BLK_K;
  int SplitK = 128;
  if (SplitK > totalKTiles) SplitK = totalKTiles;
  if (SplitK < 1) SplitK = 1;
  int kTilesPerBlock = (totalKTiles + SplitK - 1) / SplitK;
  dim3 dimBlock(256);
  dim3 dimGrid(M / BLK_M, N / BLK_N, SplitK);
  // Double-buffered shared memory: 2 buffers each for A (128x32) and B (32x128) tiles.
  constexpr int SMEM_LD = BLK_M + SMEM_PAD; // padded leading dimension (matches device kernel)
  size_t smem_size = static_cast<size_t>(4) * SMEM_LD * BLK_K * sizeof(float);
  auto kernel = gemm_splitk_device<float, float, float>;
  static bool attr_set = false;
  if (!attr_set) {
    cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_size);
    attr_set = true;
  }
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  kernel<<<dimGrid, dimBlock, smem_size, stream>>>(
      shape_MNK, kTilesPerBlock, totalKTiles,
      ptrA, dA, ptrB, dB, ptrC, dC);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE split-K gemm launch failed: ", cudaGetErrorString(err));
  return C;
}
"""

cute_gemm_ext = load_inline(
    name="cute_gemm_splitk_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B)
    with a large K dimension, implemented as a custom split-K CUTE GEMM kernel.
    """
    def __init__(self) -> None:
        super().__init__()
        self._ext = cute_gemm_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

